import { readFileSync, writeFileSync } from "node:fs";
import "../economy-audit/source-loader.mjs";
import { authoredRationales, collectAuthoredMetadata, inventoryRelease, preAnswerFields } from "./bank.mjs";
import { lintQuestion } from "./lint.mjs";

const d = await import("../../packages/clinical-content/src/index.ts");
const metadata = collectAuthoredMetadata(d);
const snapshot = JSON.parse(readFileSync(new URL("fixtures/pilot-before-20261028.json", import.meta.url), "utf8"));
const priorCases = d.applyQuestionQualityRevisions(d.QUESTION_QUALITY_SOURCE_RELEASE.cases, d.QUESTION_QUALITY_PRIOR_REVISIONS);
const cell = s => String(s ?? "—").replaceAll("|", "\\|").replaceAll("\n", "<br>");
const options = n => [...n.answerChoices].sort((a, b) => Number(b.isCorrect) - Number(a.isCorrect))
  .map(c => (c.isCorrect ? "**KEY:** " : "") + cell(c.label) + " (`" + c.id + "`)").join("<br>");
const findCase = (cases, r) => cases.find(c => c.id === r.caseId);
const findNode = (c, id) => c.decisionNodes.find(n => n.id === id);
const lintCase = (c, n, concept) => lintQuestion({
  variantId: n.questionVariantId, caseId: c.id, choices: n.answerChoices,
  fields: preAnswerFields(c, c.decisionNodes.indexOf(n)), concept,
  rationales: authoredRationales(metadata.questions.get(n.questionVariantId) ?? [], n.answerChoices),
});
const describe = r => r.findings.length ? r.findings.map(f => "`" + f.rule + "`: " + f.evidence.map(e =>
  "`" + e.field + (e.choiceId ? "[" + e.choiceId + "]" : "") + "` “" + cell(e.text) + "”").join("; ")).join("<br>")
  : "No lexical findings; this does not establish clinical validity.";
const taskWarnings = r => ({ findings: r.findings.filter(f => f.evidence.some(e => e.field === "stem") &&
  ["key-only-word-overlap", "key-only-phrase-overlap", "key-test-name-in-context", "diagnosis-disclosed", "lead-in-decision-principle", "key-rationale-principle-cue"].includes(f.rule)) });
const before = inventoryRelease(d.QUESTION_QUALITY_SOURCE_RELEASE, metadata);
const after = inventoryRelease(d.SYNTHETIC_CLINICAL_RELEASE, metadata, {
  pilotRevisions: d.QUESTION_QUALITY_REVISIONS,
  tutorialCaseIds: [d.FIRST_TUTORIAL_CASE_ID, d.SECOND_TUTORIAL_CASE_ID],
});
const changed = d.QUESTION_QUALITY_REVISIONS.filter(r => r.leadInReview.changed);
const lines = ["# Question-quality pilot review — 2026-10-28; manager review 2026-10-29", "",
  "**OWNER REVIEW HOLD: local working-tree drafts only. These rewrites must not ship until the owner reviews them. Every revised question and clinical statement remains `needs_clinician_review`; named clinician approval of the exact version is also required. Key shown first for review only. Runtime choices are randomized.**", "",
  "Owner approval concerns difficulty intent, credible three/four-option sets and no correctness analytics; it does not approve this clinical wording. No resident-performance result is claimed.", "",
  "This pilot covers all eight manual option-aligned-exclusion cases (A06/A08/A17/A27/A28/A30/A38/A40), all three direct keyed-action disclosures (A02/A23/A25), and all five supplied-interpretation cases (A04/A11/A22 plus A27/A28): 14 distinct pilot tasks and five context companions. The 2026-10-29 pass reviews all 19 for relocated task cues, pre-answer teaching, named decision principles and task/key word echoes. Sixteen drafts now have `.r3` / `question-authoring.2026-10-28.v2` identities; A04/A06/A08 retain `.r2` / v1. The original records and all prior local `.r2` drafts remain reconstructible. No concept ID or clinical meaning is intentionally changed; clinicians must confirm semantic equivalence.", "",
  "Standard: [question-authoring-standard.md](../clinical/question-authoring-standard.md). Sources: [source records](sources-question-writing-20261028.md). Full bank: [inventory](question-inventory-20261028.md). Current [versioned data](../../packages/clinical-content/src/question-quality-pilot-20261028-data.ts), retained [prior local drafts](../../packages/clinical-content/src/question-quality-pilot-20261028-r2.ts), and [evidence](../../packages/clinical-content/src/question-quality-pilot-evidence-20261028.ts).", "",
  "## Quantitative scope and limits", "",
  `Whole bank under the same current linter: ${before.totals.variantsWithFindings}/${before.totals.uniqueVariants} variant IDs and ${before.totals.findings} distinct contextual warnings before the pilot; ${after.totals.variantsWithFindings}/${after.totals.uniqueVariants} and ${after.totals.findings} after. Overlapping warnings are not verified flaws. Counts include finite profiles and visible prior feedback; canonical counts below count warning occurrences, whereas bank totals merge identical rule/field/phrase signatures. Each comparison uses the same rules. Removing a warning is not evidence of increased discrimination.`, "",
  `The conditional rationale comparison has complete explicit per-choice metadata for ${after.totals.variantsWithCompleteRationales}/${after.totals.uniqueVariants} live variants. Missing or conflicting reasons make that comparison ineligible. Post-answer reasons are never included as pre-answer overlap text. The broad lead-in principle warning also works without rationale metadata.`, "",
  "| Pilot | Original variant | Current variant | Canonical warnings before → after | Intent |", "|---|---|---|---:|---|"];
const details = [];
for (const old of snapshot.items) {
