  const lb = lintCase(old.case, a, old.concept), la = lintCase(c, b, metadata.concepts.get(b.primaryConceptId));
  const allBefore = before.variants.find(v => v.questionVariantId === r.previousQuestionVariantId);
  const allAfter = after.variants.find(v => v.questionVariantId === r.questionVariantId);
  lines.push(`| ${r.auditId} | ${r.previousQuestionVariantId} | ${r.questionVariantId} | ${lb.findings.length} → ${la.findings.length} | ${r.educationalIntent} |`);
  details.push("", "## " + r.auditId + " — " + cell(old.concept?.displayName ?? b.primaryConceptId), "",
    "Case: `" + r.caseId + "`; node: `" + r.nodeId + "`; stable concept: `" + b.primaryConceptId + "`. Facility entry index " + c.earliestFacilityStage + "; educational tier " + (old.concept?.educationalTier ?? "unmapped") + ". Current content version: `" + r.question.contentVersion + "`; original: " + r.previousContentVersions.map(v => "`" + v + "`").join(", ") + ".", "",
    "**Draft; needs_clinician_review; owner review hold. Key shown first for review only.**", "",
    "| Field | Before pilot (project-owned text) | Current draft |", "|---|---|---|",
    "| Presentation | " + cell(old.case.presentation) + " | " + cell(c.presentation) + " |",
    "| Current update | " + cell(a.currentUpdate) + " | " + cell(b.currentUpdate) + " |",
    "| Task | " + cell(a.stem) + " | " + cell(b.stem) + " |",
    "| Options | " + options(a) + " | " + options(b) + " |",
    "| Exhibit | " + cell(a.exhibit ? JSON.stringify(a.exhibit) : null) + " | " + cell(b.exhibit ? JSON.stringify(b.exhibit) : null) + " |", "",
    "Intended inference: " + r.intendedInference, "", "Review focus: " + r.reviewerNotes, "",
    "| Current choice (key shown first for review only) | Why it tempts / deciding inference |", "|---|---|",
    ...r.question.answerChoices.map(c => "| " + (c.isCorrect ? "**KEY:** " : "") + cell(c.label) + " | " + cell(c.rationale ?? c.distractorRationale) + " |"), "",
